import { Redis } from "ioredis";

const redis = new Redis();

/**
 * Builds the per-post Redis key that stores the collection of user ids
 * who liked a given post.
 */
function likesKey(postId: string): string {
  return `likes:post:${postId}`;
}

/**
 * Checks whether a user has already liked a post.
 *
 * BUG: pulls the full liker list into the app and scans it in memory.
 */
async function hasLiked(postId: string, userId: string): Promise<boolean> {
  const key = likesKey(postId);
  const members: string[] = await redis.lrange(key, 0, -1);
  return members.includes(userId);
}

/**
 * Records that a user liked a post.
 *
 * BUG: appends unconditionally, so liking twice pushes the same userId twice.
 */
async function addLike(postId: string, userId: string): Promise<void> {
  const key = likesKey(postId);
  await redis.rpush(key, userId);
}

export { likesKey, hasLiked, addLike };
